/**
 * Account
 * For new integrations, we recommend using the [Accounts v2 API](/api/v2/core/accounts), in place of /v1/accounts and /v1/customers to represent a user.
 *
 * This is an object representing a Stripe account. You can retrieve it to see
 * properties on the account like its current requirements or if the account is
 * enabled to make live charges or receive payouts.
 *
 * For accounts where [controller.requirement_collection](/api/accounts/object#account_object-controller-requirement_collection)
 * is `application`, which includes Custom accounts, the properties below are always
 * returned.
 *
 * For accounts where [controller.requirement_collection](/api/accounts/object#account_object-controller-requirement_collection)
 * is `stripe`, which includes Standard and Express accounts, some properties are only returned
 * until you create an [Account Link](/api/account_links) or [Account Session](/api/account_sessions)
 * to start Connect Onboarding. Learn about the [differences between accounts](/connect/accounts).
 */
export const zAccount = z.object({
    business_profile: z.optional(z.union([
        zAccountBusinessProfile,
        z.null()
    ])),
    business_type: z.optional(z.enum([
        'company',
        'government_entity',
        'individual',
        'non_profit'
    ])),
    capabilities: z.optional(zAccountCapabilities),
    charges_enabled: z.optional(z.boolean()),
    company: z.optional(zLegalEntityCompany),
    controller: z.optional(zAccountUnificationAccountController),
    country: z.optional(z.string().max(5000)),
    created: z.optional(z.int()),
    default_currency: z.optional(z.string().max(5000)),
    details_submitted: z.optional(z.boolean()),
    email: z.optional(z.union([
        z.string().max(5000),
        z.null()
    ])),
    get external_accounts(): z.ZodOptional {
        return z.optional(z.object({
            get data() {
                return z.array(z.union([
                    zBankAccount,
                    zCard
                ]));
            },
            has_more: z.boolean(),
            object: z.enum([
                'list'
            ]),
            url: z.string().max(5000)
        }));
    },
    future_requirements: z.optional(zAccountFutureRequirements),
    groups: z.optional(z.union([
        zAccountGroupMembership,
        z.null()
    ])),
    id: z.string().max(5000),
    individual: z.optional(zPerson),
    metadata: z.optional(z.record(z.string(), z.string().max(500))),
    object: z.enum([
        'account'
    ]),
    payouts_enabled: z.optional(z.boolean()),
    requirements: z.optional(zAccountRequirements),
    settings: z.optional(z.union([
        zAccountSettings,
        z.null()
    ])),
    tos_acceptance: z.optional(zAccountTosAcceptance),
    type: z.optional(z.enum([
        'custom',
        'express',
        'none',
        'standard'
    ]))
});

