/**
 * Source
 * `Source` objects allow you to accept a variety of payment methods. They
 * represent a customer's payment instrument, and can be used with the Stripe API
 * just like a `Card` object: once chargeable, they can be charged, or can be
 * attached to customers.
 *
 * Stripe doesn't recommend using the deprecated [Sources API](https://docs.stripe.com/api/sources).
 * We recommend that you adopt the [PaymentMethods API](https://docs.stripe.com/api/payment_methods).
 * This newer API provides access to our latest features and payment method types.
 *
 * Related guides: [Sources API](https://docs.stripe.com/sources) and [Sources & Customers](https://docs.stripe.com/sources/customers).
 */
export const zSource = z.object({
    ach_credit_transfer: z.optional(zSourceTypeAchCreditTransfer),
    ach_debit: z.optional(zSourceTypeAchDebit),
    acss_debit: z.optional(zSourceTypeAcssDebit),
    alipay: z.optional(zSourceTypeAlipay),
    allow_redisplay: z.optional(z.enum([
        'always',
        'limited',
        'unspecified'
    ])),
    amount: z.optional(z.union([
        z.int(),
        z.null()
    ])),
    au_becs_debit: z.optional(zSourceTypeAuBecsDebit),
    bancontact: z.optional(zSourceTypeBancontact),
    card: z.optional(zSourceTypeCard),
    card_present: z.optional(zSourceTypeCardPresent),
    client_secret: z.string().max(5000),
    code_verification: z.optional(zSourceCodeVerificationFlow),
    created: z.int(),
    currency: z.optional(z.union([
        z.string(),
        z.null()
    ])),
    customer: z.optional(z.string().max(5000)),
    eps: z.optional(zSourceTypeEps),
    flow: z.string().max(5000),
    giropay: z.optional(zSourceTypeGiropay),
    id: z.string().max(5000),
    ideal: z.optional(zSourceTypeIdeal),
    klarna: z.optional(zSourceTypeKlarna),
    livemode: z.boolean(),
    metadata: z.optional(z.union([
        z.record(z.string(), z.string().max(500)),
        z.null()
    ])),
    multibanco: z.optional(zSourceTypeMultibanco),
    object: z.enum([
        'source'
    ]),
    owner: z.optional(z.union([
        zSourceOwner,
        z.null()
    ])),
    p24: z.optional(zSourceTypeP24),
    receiver: z.optional(zSourceReceiverFlow),
    redirect: z.optional(zSourceRedirectFlow),
    sepa_debit: z.optional(zSourceTypeSepaDebit),
    sofort: z.optional(zSourceTypeSofort),
    source_order: z.optional(zSourceOrder),
    statement_descriptor: z.optional(z.union([
        z.string().max(5000),
        z.null()
    ])),
    status: z.string().max(5000),
    three_d_secure: z.optional(zSourceTypeThreeDSecure),
    type: z.enum([
        'ach_credit_transfer',
        'ach_debit',
        'acss_debit',
        'alipay',
        'au_becs_debit',
        'bancontact',
        'card',
        'card_present',
        'eps',
        'giropay',
        'ideal',
        'klarna',
        'multibanco',
        'p24',
        'sepa_debit',
        'sofort',
        'three_d_secure',
        'wechat'
    ]),
    usage: z.optional(z.union([
        z.string().max(5000),
        z.null()
    ])),
    wechat: z.optional(zSourceTypeWechat)
});

