/**
 * Coupon
 * A coupon contains information about a percent-off or amount-off discount you
 * might want to apply to a customer. Coupons may be applied to [subscriptions](https://api.stripe.com#subscriptions), [invoices](https://api.stripe.com#invoices),
 * [checkout sessions](https://docs.stripe.com/api/checkout/sessions), [quotes](https://api.stripe.com#quotes), and more. Coupons do not work with conventional one-off [charges](/api/charges/create) or [payment intents](https://docs.stripe.com/api/payment_intents).
 */
export const zCoupon = z.object({
    amount_off: z.optional(z.union([
        z.int(),
        z.null()
    ])),
    applies_to: z.optional(zCouponAppliesTo),
    created: z.int(),
    currency: z.optional(z.union([
        z.string(),
        z.null()
    ])),
    currency_options: z.optional(z.record(z.string(), zCouponCurrencyOption)),
    duration: z.enum([
        'forever',
        'once',
        'repeating'
    ]),
    duration_in_months: z.optional(z.union([
        z.int(),
        z.null()
    ])),
    id: z.string().max(5000),
    livemode: z.boolean(),
    max_redemptions: z.optional(z.union([
        z.int(),
        z.null()
    ])),
    metadata: z.optional(z.union([
        z.record(z.string(), z.string().max(500)),
        z.null()
    ])),
    name: z.optional(z.union([
        z.string().max(5000),
        z.null()
    ])),
    object: z.enum([
        'coupon'
    ]),
    percent_off: z.optional(z.union([
        z.number(),
        z.null()
    ])),
    redeem_by: z.optional(z.union([
        z.int(),
        z.null()
    ])),
    times_redeemed: z.int(),
    valid: z.boolean()
});

