/**
 * Dispute
 * A dispute occurs when a customer questions your charge with their card issuer.
 * When this happens, you have the opportunity to respond to the dispute with
 * evidence that shows that the charge is legitimate.
 *
 * Related guide: [Disputes and fraud](https://docs.stripe.com/disputes)
 */
export const zDispute = z.object({
    amount: z.int(),
    get balance_transactions() {
        return z.array(zBalanceTransaction);
    },
    charge: z.union([
        z.string().max(5000),
        zCharge
    ]),
    created: z.int(),
    currency: z.string(),
    enhanced_eligibility_types: z.array(z.enum([
        'mastercard_compliance',
        'visa_compelling_evidence_3',
        'visa_compliance'
    ])),
    evidence: zDisputeEvidence,
    evidence_details: zDisputeEvidenceDetails,
    id: z.string().max(5000),
    is_charge_refundable: z.boolean(),
    livemode: z.boolean(),
    metadata: z.record(z.string(), z.string().max(500)),
    object: z.enum([
        'dispute'
    ]),
    payment_intent: z.optional(z.union([
        z.string().max(5000),
        zPaymentIntent,
        z.null()
    ])),
    payment_method_details: z.optional(zDisputePaymentMethodDetails),
    reason: z.string().max(5000),
    status: z.enum([
        'lost',
        'needs_response',
        'prevented',
        'under_review',
        'warning_closed',
        'warning_needs_response',
        'warning_under_review',
        'won'
    ])
});

