/**
 * IssuingPersonalizationDesign
 * A Personalization Design is a logical grouping of a Physical Bundle, card logo, and carrier text that represents a product line.
 */
export const zIssuingPersonalizationDesign = z.object({
    card_logo: z.optional(z.union([
        z.string().max(5000),
        zFile,
        z.null()
    ])),
    carrier_text: z.optional(z.union([
        zIssuingPersonalizationDesignCarrierText,
        z.null()
    ])),
    created: z.int(),
    id: z.string().max(5000),
    livemode: z.boolean(),
    lookup_key: z.optional(z.union([
        z.string().max(5000),
        z.null()
    ])),
    metadata: z.record(z.string(), z.string().max(500)),
    name: z.optional(z.union([
        z.string().max(5000),
        z.null()
    ])),
    object: z.enum([
        'issuing.personalization_design'
    ]),
    physical_bundle: z.union([
        z.string().max(5000),
        zIssuingPhysicalBundle
    ]),
    preferences: zIssuingPersonalizationDesignPreferences,
    rejection_reasons: zIssuingPersonalizationDesignRejectionReasons,
    status: z.enum([
        'active',
        'inactive',
        'rejected',
        'review'
    ])
});

