/**
 * RadarReview
 * Reviews can be used to supplement automated fraud detection with human expertise.
 *
 * Learn more about [Radar](/radar) and reviewing payments
 * [here](https://docs.stripe.com/radar/reviews).
 */
export const zReview = z.object({
    billing_zip: z.optional(z.union([
        z.string().max(5000),
        z.null()
    ])),
    charge: z.optional(z.union([
        z.string().max(5000),
        zCharge,
        z.null()
    ])),
    closed_reason: z.optional(z.enum([
        'acknowledged',
        'approved',
        'canceled',
        'disputed',
        'payment_never_settled',
        'redacted',
        'refunded',
        'refunded_as_fraud'
    ])),
    created: z.int(),
    id: z.string().max(5000),
    ip_address: z.optional(z.union([
        z.string().max(5000),
        z.null()
    ])),
    ip_address_location: z.optional(z.union([
        zRadarReviewResourceLocation,
        z.null()
    ])),
    livemode: z.boolean(),
    object: z.enum([
        'review'
    ]),
    open: z.boolean(),
    opened_reason: z.enum([
        'manual',
        'rule'
    ]),
    payment_intent: z.optional(z.union([
        z.string().max(5000),
        zPaymentIntent
    ])),
    reason: z.string().max(5000),
    session: z.optional(z.union([
        zRadarReviewResourceSession,
        z.null()
    ]))
});

/**
 * ChargeTransferData
 */
export const zChargeTransferData = z.object({
    amount: z.optional(z.union([
        z.int(),
        z.null()
    ])),
    destination: z.union([
        z.string().max(5000),
        zAccount
    ])
});

/**
 * Charge
 * The `Charge` object represents a single attempt to move money into your Stripe account.
 * PaymentIntent confirmation is the most common way to create Charges, but [Account Debits](https://docs.stripe.com/connect/account-debits) may also create Charges.
 * Some legacy payment flows create Charges directly, which is not recommended for new integrations.
 */
export const zCharge = z.object({
    amount: z.int(),
    amount_captured: z.int(),
    amount_refunded: z.int(),
    application: z.optional(z.union([
        z.string().max(5000),
        zApplication,
        z.null()
    ])),
    application_fee: z.optional(z.union([
        z.string().max(5000),
        zApplicationFee,
        z.null()
    ])),
    application_fee_amount: z.optional(z.union([
        z.int(),
        z.null()
    ])),
    balance_transaction: z.optional(z.union([
        z.string().max(5000),
        zBalanceTransaction,
        z.null()
    ])),
    billing_details: zBillingDetails,
    calculated_statement_descriptor: z.optional(z.union([
        z.string().max(5000),
        z.null()
    ])),
    captured: z.boolean(),
    created: z.int(),
    currency: z.string(),
    customer: z.optional(z.union([
        z.string().max(5000),
        zCustomer,
        zDeletedCustomer,
        z.null()
    ])),
    description: z.optional(z.union([
        z.string().max(40000),
        z.null()
    ])),
    disputed: z.boolean(),
    failure_balance_transaction: z.optional(z.union([
        z.string().max(5000),
        zBalanceTransaction,
        z.null()
    ])),
    failure_code: z.optional(z.union([
        z.string().max(5000),
        z.null()
    ])),
    failure_message: z.optional(z.union([
        z.string().max(5000),
        z.null()
    ])),
    fraud_details: z.optional(z.union([
        zChargeFraudDetails,
        z.null()
    ])),
    id: z.string().max(5000),
    livemode: z.boolean(),
    metadata: z.record(z.string(), z.string().max(500)),
    object: z.enum([
        'charge'
    ]),
    on_behalf_of: z.optional(z.union([
        z.string().max(5000),
        zAccount,
        z.null()
    ])),
    outcome: z.optional(z.union([
        zChargeOutcome,
        z.null()
    ])),
    paid: z.boolean(),
    payment_intent: z.optional(z.union([
        z.string().max(5000),
        zPaymentIntent,
        z.null()
    ])),
    payment_method: z.optional(z.union([
        z.string().max(5000),
        z.null()
    ])),
    payment_method_details: z.optional(z.union([
        zPaymentMethodDetails,
        z.null()
    ])),
    presentment_details: z.optional(zPaymentFlowsPaymentIntentPresentmentDetails),
    radar_options: z.optional(zRadarRadarOptions),
    receipt_email: z.optional(z.union([
        z.string().max(5000),
        z.null()
    ])),
    receipt_number: z.optional(z.union([
        z.string().max(5000),
        z.null()
    ])),
    receipt_url: z.optional(z.union([
        z.string().max(5000),
        z.null()
    ])),
    refunded: z.boolean(),
    refunds: z.optional(z.union([
        z.object({
            data: z.array(zRefund),
            has_more: z.boolean(),
            object: z.enum([
                'list'
            ]),
            url: z.string().max(5000)
        }),
        z.null()
    ])),
    review: z.optional(z.union([
        z.string().max(5000),
        zReview,
        z.null()
    ])),
    shipping: z.optional(z.union([
        zShipping,
        z.null()
    ])),
    source_transfer: z.optional(z.union([
        z.string().max(5000),
        zTransfer,
        z.null()
    ])),
    statement_descriptor: z.optional(z.union([
        z.string().max(5000),
        z.null()
    ])),
    statement_descriptor_suffix: z.optional(z.union([
        z.string().max(5000),
        z.null()
    ])),
    status: z.enum([
        'failed',
        'pending',
        'succeeded'
    ]),
    transfer: z.optional(z.union([
        z.string().max(5000),
        zTransfer
    ])),
    transfer_data: z.optional(z.union([
        zChargeTransferData,
        z.null()
    ])),
    transfer_group: z.optional(z.union([
        z.string().max(5000),
        z.null()
    ]))
});

